// PreToolUse: recibe la llamada en JSON por stdin. Exit 2 bloquea y stderr llega al modelo.
let input = '';
for await (const chunk of process.stdin) input += chunk;

const command = JSON.parse(input).tool_input?.command ?? '';
const forbidden = [/\brm\s+-[a-z]*r[a-z]*f/i, /\bgit\s+push\b.*--force/];

if (forbidden.some((rule) => rule.test(command))) {
  console.error(`Bloqueado por política del proyecto: ${command}`);
  process.exit(2);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { conIva } from './iva.js';

